automatic.toastText:
  :host{all:initial}
  @media (prefers-reduced-motion:no-preference) {
    .card{animation:enter .32s ease-out both}
    @keyframes enter{from{transform:translateX(110%);opacity:0}to{transform:translateX(0);opacity:1}}
